class DataLoadWorker(QRunnable):
    def __init__(self, path: str, selected_wells=None):
        super().__init__()
        self.path = path
        self.selected_wells = selected_wells
        self.signals = WorkerSignals()
        self._cancel_requested = False

    def cancel(self) -> None:
        self._cancel_requested = True

    def _is_cancelled(self) -> bool:
        return bool(self._cancel_requested)

    def _check_cancelled(self) -> None:
        if self._is_cancelled():
            raise InterruptedError("Data loading cancelled")

    @Slot()
    def run(self):
        try:
            suffix = Path(self.path).suffix.lower()
            self._check_cancelled()
            self.signals.progress.emit(5, "Opening data file...")
            if suffix == ".nev":
                self.signals.progress.emit(20, "Reading NEV file...")
                raw_data = read_blackrock_nev(self.path, cancel_check=self._is_cancelled)
                data_kind = "nev"
            elif suffix == ".spk":
                well_text = ", ".join(self.selected_wells) if self.selected_wells else "all wells"
                self.signals.progress.emit(20, f"Reading Axion SPK data ({well_text})...")
                self._check_cancelled()
                raw_data = read_axion_spk(self.path, wells=self.selected_wells)
                data_kind = "nev"
            elif suffix in {".h5", ".hdf5"}:
                self.signals.progress.emit(18, "Reading Maxwell H5 metadata...")
                self.signals.progress.emit(25, "Extracting Maxwell spikes...")
                raw_data = read_maxwell_h5(self.path, cancel_check=self._is_cancelled, extract_waveforms=False)
                data_kind = "nev"
            else:
                self.signals.progress.emit(20, "Reading data file...")
                self._check_cancelled()
                raw_data = MEAReader(self.path).load_data()
                data_kind = "nev" if isinstance(raw_data, UnifiedMEAData) else "array"
            self._check_cancelled()
            self.signals.progress.emit(92, "Preparing loaded data...")
            self.signals.finished.emit({"path": self.path, "raw_data": raw_data, "data_kind": data_kind})
        except InterruptedError as exc:
            self.signals.canceled.emit(str(exc) or "Data loading cancelled")
        except Exception:
            self.signals.failed.emit(traceback.format_exc())


def _load_gui_data_file(path: str | Path, *, selected_wells=None, cancel_check=None):
    path = Path(path)
    suffix = path.suffix.lower()
    if cancel_check is not None and cancel_check():
        raise InterruptedError("Data loading cancelled")
    if suffix == ".nev":
        raw_data = read_blackrock_nev(path, cancel_check=cancel_check)
        data_kind = "nev"
    elif suffix == ".spk":
        raw_data = read_axion_spk(path, wells=selected_wells)
        data_kind = "nev"
    elif suffix in {".h5", ".hdf5"}:
        raw_data = read_maxwell_h5(path, cancel_check=cancel_check, extract_waveforms=False)
        data_kind = "nev"
    else:
        raw_data = MEAReader(path).load_data()
        data_kind = "nev" if isinstance(raw_data, UnifiedMEAData) else "array"
    return raw_data, data_kind


def _loaded_data_kind_label(data, data_kind: str = "") -> str:
    if isinstance(data, UnifiedMEAData) and isinstance(data.meta, dict):
        source = str(data.meta.get("source", "") or "")
        if source:
            return source
    return str(data_kind or type(data).__name__)


def _loaded_data_stats(data) -> tuple[int, int, int]:
    if isinstance(data, UnifiedMEAData):
        channels = len(data.channels())
        spikes = int(sum(np.asarray(values).size for values in data.spikes.values()))
        waveforms = len(data.waveforms)
        return channels, spikes, waveforms
    array = np.asarray(data) if data is not None else np.asarray([])
    channels = int(array.shape[0]) if array.ndim >= 1 else 0
    return channels, int(array.size), 0


def _loaded_data_stats_lightweight(data) -> tuple[int, str, int]:
    if isinstance(data, UnifiedMEAData):
        channels = len(data.spikes)
        waveforms = len(data.waveforms)
        spike_total = None
        if isinstance(data.meta, dict):
            for key in ("spike_count", "total_spikes", "event_count"):
                value = data.meta.get(key)
                try:
                    if value is not None:
                        spike_total = int(value)
                        break
                except (TypeError, ValueError):
                    continue
        return channels, str(spike_total) if spike_total is not None else "deferred", waveforms
    if data is None:
        return 0, "0", 0
    shape = getattr(data, "shape", None)
    if shape is not None:
        try:
            channels = int(shape[0]) if len(shape) >= 1 else 0
            size = int(np.prod(shape)) if shape else 0
            return channels, str(size), 0
        except Exception:
            pass
    return 0, "deferred", 0


def _loaded_data_activity_label(path: str | Path, data=None) -> str:
    params = _extract_stimulus_parameters(path)
    activity = str(params.get("activity", "")).strip().lower()
    if activity == "spont":
        return "Spontaneous"
    if isinstance(data, UnifiedMEAData):
        stim_times = np.asarray(getattr(data, "stim_times", []), dtype=float)
        if np.count_nonzero(np.isfinite(stim_times)) > 0:
            return "Stimulus"
        if isinstance(data.meta, dict):
            event_count = data.meta.get("event_count", 0)
            try:
                if int(event_count) > 0:
                    return "Stimulus"
            except (TypeError, ValueError):
                pass
    if "stim_electrode" in params or str(params.get("stim_mode", "")).strip().lower() == "multi-site":
        return "Stimulus"
    return "Spontaneous"


def _loaded_data_activity_sort_key(label: str) -> tuple[int, str]:
    text = str(label or "")
    order = {"Stimulus": 0, "Spontaneous": 1}
    return (order.get(text, 2), text.lower())


def _generic_analysis_matrix_from_record(
    record,
    *,
    view_mode: str = "auto",
    bin_ms: float = 10.0,
    burst_window_ms: float = 300.0,
    burst_threshold_z: float = 4.0,
    array_axis: str = "rows",
) -> tuple[np.ndarray, list[str], str]:
    """Convert a loaded database record into a generic samples x features matrix."""

    raw_data = (record or {}).get("raw_data")
    view_mode = str(view_mode or "auto").strip().lower()
    if isinstance(raw_data, UnifiedMEAData):
        spike_series = _spike_series_from_unified(raw_data)
        if not spike_series:
            return np.zeros((0, 0), dtype=float), [], "No spike-event channels"
        channel_labels = [str(label) for label, _times in spike_series]
        start_s, stop_s = raw_data.time_range()
        bin_s = max(1e-3, float(bin_ms) / 1000.0)
        if stop_s <= start_s:
            stop_s = start_s + bin_s
        edges = np.arange(start_s, stop_s + bin_s, bin_s, dtype=float)
        if edges.size < 2:
            edges = np.array([start_s, start_s + bin_s], dtype=float)
        rows = []
        for _label, times in spike_series:
            counts, _ = np.histogram(np.asarray(times, dtype=float), bins=edges)
            rows.append(np.asarray(counts, dtype=float))
        channel_time = np.vstack(rows) if rows else np.zeros((0, max(0, edges.size - 1)), dtype=float)
        burst_intervals = _detect_burst_intervals(
            spike_series,
            bin_ms=float(bin_ms),
            threshold_z=float(burst_threshold_z),
            min_spikes=5,
        )
        burst_labels, burst_intervals, burst_activity = _burst_activity_matrix(
            spike_series,
            burst_intervals,
            time_bin_ms=float(bin_ms),
            window_ms=float(burst_window_ms),
        )
        if view_mode in {"auto", "channel_time"}:
            description = f"Channel x time-bin spike-count matrix | channels={len(channel_labels)} | bins={channel_time.shape[1]} | bin={float(bin_ms):g} ms"
            return channel_time, channel_labels, description
        if view_mode == "time_channel":
            labels = [f"bin {index + 1}" for index in range(channel_time.shape[1])]
            description = f"Time-bin x channel spike-count matrix | bins={channel_time.shape[1]} | channels={len(channel_labels)} | bin={float(bin_ms):g} ms"
            return channel_time.T, labels, description
        if view_mode == "burst_flat":
            if burst_activity.ndim == 3 and burst_activity.shape[0] > 0:
                matrix = burst_activity.reshape((burst_activity.shape[0], burst_activity.shape[1] * burst_activity.shape[2]))
            else:
                matrix = np.zeros((0, 0), dtype=float)
            labels = [f"burst {index + 1}" for index in range(matrix.shape[0])]
            description = (
                f"Burst x flattened(channel,time) matrix | bursts={matrix.shape[0]} | channels={len(burst_labels)} | "
                f"bins/window={burst_activity.shape[2] if burst_activity.ndim == 3 else 0} | bin={float(bin_ms):g} ms | window={float(burst_window_ms):g} ms"
            )
            return matrix, labels, description
        if view_mode == "channel_burst":
            if burst_activity.ndim == 3 and burst_activity.shape[0] > 0:
                matrix = np.transpose(burst_activity, (1, 0, 2)).reshape((burst_activity.shape[1], burst_activity.shape[0] * burst_activity.shape[2]))
            else:
                matrix = np.zeros((0, 0), dtype=float)
            description = (
                f"Channel x flattened(burst,time) matrix | channels={len(burst_labels)} | bursts={burst_activity.shape[0] if burst_activity.ndim == 3 else 0} | "
                f"bins/window={burst_activity.shape[2] if burst_activity.ndim == 3 else 0} | bin={float(bin_ms):g} ms | window={float(burst_window_ms):g} ms"
            )
            return matrix, [str(label) for label in burst_labels], description
        description = f"Channel x time-bin spike-count matrix | channels={len(channel_labels)} | bins={channel_time.shape[1]} | bin={float(bin_ms):g} ms"
        return channel_time, channel_labels, description

    array = np.nan_to_num(np.asarray(raw_data, dtype=float), nan=0.0, posinf=0.0, neginf=0.0) if raw_data is not None else np.zeros((0, 0), dtype=float)
    if array.ndim == 0:
        array = array.reshape((1, 1))
    elif array.ndim == 1:
        array = array.reshape((1, -1))
    elif array.ndim > 2:
        first_dim = int(array.shape[0]) if array.shape else 0
        array = array.reshape((first_dim, -1))
    axis_mode = str(array_axis or "rows").strip().lower()
    if axis_mode == "columns" and array.ndim == 2:
        array = array.T
        labels = [f"column {index + 1}" for index in range(array.shape[0])]
        description = f"Array matrix | samples=columns | rows={array.shape[1]} | columns={array.shape[0]}"
        return np.asarray(array, dtype=float), labels, description
    labels = [f"row {index + 1}" for index in range(array.shape[0])] if array.ndim >= 2 else []
    description = f"Array matrix | samples=rows | rows={array.shape[0] if array.ndim >= 1 else 0} | features={array.shape[1] if array.ndim >= 2 else 0}"
    return np.asarray(array, dtype=float), labels, description


def _parse_optional_float_list(text: str) -> np.ndarray:
    values = []
    for token in re.split(r"[\s,;]+", str(text or "").strip()):
        if not token:
            continue
        values.append(float(token))
    return np.asarray(values, dtype=float)


def _natural_sort_key(value) -> tuple:
    parts = re.split(r"(\d+)", str(value or ""))
    key = []
    for part in parts:
        if part.isdigit():
            key.append((0, int(part)))
        else:
            key.append((1, part.lower()))
    return tuple(key)


def _parse_custom_time_windows(text: str, data: UnifiedMEAData) -> list[tuple[float, float, str]]:
    raw = str(text or "full").strip()
    start_s, stop_s = data.time_range()
    if stop_s <= start_s:
        finite = [np.asarray(times, dtype=float) for _label, times in _spike_series_from_unified(data) if np.asarray(times, dtype=float).size]
        if finite:
            stop_s = max(float(np.nanmax(values)) for values in finite if values.size)
        stop_s = max(stop_s, start_s + 1.0)
    if not raw or raw.lower() in {"full", "all", "*"}:
        return [(float(start_s), float(stop_s), f"{float(start_s):g}-{float(stop_s):g}s")]
    windows: list[tuple[float, float, str]] = []
    for chunk in re.split(r"[,;]+", raw):
        chunk = chunk.strip()
        if not chunk:
            continue
        match = re.match(r"^\s*([+-]?\d+(?:\.\d+)?)\s*(?:-|:|to)\s*([+-]?\d+(?:\.\d+)?)\s*$", chunk, re.IGNORECASE)
        if not match:
            raise ValueError(f"Invalid time window: {chunk}")
        lo = float(match.group(1))
        hi = float(match.group(2))
        if hi <= lo:
            raise ValueError(f"Time window stop must be greater than start: {chunk}")
        windows.append((lo, hi, f"{lo:g}-{hi:g}s"))
    if not windows:
        raise ValueError("No valid time windows were defined")
    return windows


def _custom_channel_filter(spike_series, channels_text: str):
    requested = [token.strip() for token in re.split(r"[,;]+", str(channels_text or "")) if token.strip()]
    if not requested:
        return [(str(label), np.asarray(times, dtype=float)) for label, times in spike_series]
    requested_keys = {normalize_channel_name(token) for token in requested}
    requested_keys.update(normalize_channel_name(_base_channel_from_raster_label(token)) for token in requested)
    selected = []
    for label, times in spike_series:
        candidates = {
            normalize_channel_name(str(label)),
            normalize_channel_name(_base_channel_from_raster_label(str(label))),
        }
        if candidates & requested_keys:
            selected.append((str(label), np.asarray(times, dtype=float)))
    return selected


def _custom_spike_vector_matrix(spike_series, windows, analysis_type: str):
    mode = str(analysis_type or "firing_rate_vector")
    feature_labels = [str(label) for label, _times in spike_series]
    sample_labels = [str(label) for _start, _stop, label in windows]
    matrix = np.zeros((len(windows), len(spike_series)), dtype=float)
    for row, (start_s, stop_s, _label) in enumerate(windows):
        duration_s = max(float(stop_s) - float(start_s), 1e-9)
        for col, (_channel, times) in enumerate(spike_series):
            values = np.asarray(times, dtype=float)
            count = int(np.count_nonzero((values >= float(start_s)) & (values < float(stop_s))))
            matrix[row, col] = float(count) / duration_s if mode == "firing_rate_vector" else float(count)
    if mode == "firing_rate_vector":
        description = f"Custom vector firing rate | windows={len(windows)} | channels={len(spike_series)}"
    elif mode == "spike_count_vector":
        description = f"Custom vector spike count | windows={len(windows)} | channels={len(spike_series)}"
    else:
        raise ValueError(f"Unsupported custom analysis type: {analysis_type}")
    return matrix, sample_labels, feature_labels, description


def _custom_plot_axis_mode(record: dict, requested: str = "auto") -> str:
    mode = str(requested or "auto")
    if mode != "auto":
        return mode
    matrix = np.asarray((record or {}).get("matrix", []), dtype=float)
    if matrix.ndim == 1:
        matrix = matrix.reshape((-1, 1))
    sample_labels = list((record or {}).get("sample_labels", []))
    feature_labels = list((record or {}).get("feature_labels", []))
    if matrix.ndim == 2 and matrix.shape[0] == 1 and matrix.shape[1] > 1 and feature_labels:
        return "features"
    if sample_labels and matrix.ndim == 2 and len(sample_labels) == matrix.shape[0]:
        return "sample_labels"
    return "sample_index"


def _custom_plot_x_axis(record: dict, parameters: dict | None = None):
    params = dict(parameters or {})
    matrix = np.asarray((record or {}).get("matrix", []), dtype=float)
    if matrix.ndim == 1:
        matrix = matrix.reshape((-1, 1))
    if matrix.ndim != 2:
        return np.zeros(0, dtype=float), [], "Sample", False, matrix
    mode = _custom_plot_axis_mode(record, str(params.get("x_mode", "auto") or "auto"))
    sample_labels = [str(label) for label in list((record or {}).get("sample_labels", []))]
    feature_labels = [str(label) for label in list((record or {}).get("feature_labels", []))]
    if mode == "manual":
        x = _parse_optional_float_list(str(params.get("x_values", "")))
        if matrix.shape[0] == 1 and matrix.shape[1] > 1 and x.size == matrix.shape[1]:
            return x, [], str(params.get("x_label") or "Manual x"), True, matrix
        if x.size != matrix.shape[0]:
            x = np.arange(1, matrix.shape[0] + 1, dtype=float)
        return x, [], str(params.get("x_label") or "Sample"), False, matrix
    if mode == "generated":
        try:
            start = float(params.get("x_start", 1.0))
        except (TypeError, ValueError):
            start = 1.0
        try:
            step = float(params.get("x_step", 1.0))
        except (TypeError, ValueError):
            step = 1.0
        if matrix.shape[0] == 1 and matrix.shape[1] > 1:
            x = start + np.arange(matrix.shape[1], dtype=float) * step
            return x, [], str(params.get("x_label") or "Generated x"), True, matrix
        x = start + np.arange(matrix.shape[0], dtype=float) * step
        return x, [], str(params.get("x_label") or "Generated x"), False, matrix
    if mode == "features" and matrix.shape[0] == 1:
        labels = feature_labels if len(feature_labels) == matrix.shape[1] else [f"feature {index + 1}" for index in range(matrix.shape[1])]
        return np.arange(1, matrix.shape[1] + 1, dtype=float), labels, str(params.get("x_label") or "Channel / feature"), True, matrix
    if mode == "sample_labels":
        labels = sample_labels if len(sample_labels) == matrix.shape[0] else [f"sample {index + 1}" for index in range(matrix.shape[0])]
        return np.arange(1, matrix.shape[0] + 1, dtype=float), labels, str(params.get("x_label") or "Sample"), False, matrix
    return np.arange(1, matrix.shape[0] + 1, dtype=float), [], str(params.get("x_label") or "Sample index"), False, matrix


def _custom_plot_y_options(record: dict) -> list[tuple[str, str]]:
    matrix = np.asarray((record or {}).get("matrix", []), dtype=float)
    if matrix.ndim == 1:
        matrix = matrix.reshape((-1, 1))
    if matrix.ndim != 2 or matrix.size == 0:
        return []
    feature_labels = [str(label) for label in list((record or {}).get("feature_labels", []))]
    if len(feature_labels) != matrix.shape[1]:
        feature_labels = [f"feature {index + 1}" for index in range(matrix.shape[1])]
    sample_labels = [str(label) for label in list((record or {}).get("sample_labels", []))]
    if len(sample_labels) != matrix.shape[0]:
        sample_labels = [f"sample {index + 1}" for index in range(matrix.shape[0])]
    options: list[tuple[str, str]] = []
    if matrix.shape[0] == 1 and matrix.shape[1] > 1:
        options.append(("all_features", "All features"))
        options.extend((f"feature:{index}", label) for index, label in enumerate(feature_labels))
    else:
        options.append(("all_features", "All features"))
        options.extend((f"feature:{index}", label) for index, label in enumerate(feature_labels))
        if matrix.shape[1] == 1:
            options.append(("single_feature", feature_labels[0]))
        if matrix.shape[0] > 1:
            options.extend((f"sample:{index}", f"Sample {label}") for index, label in enumerate(sample_labels))
    seen = set()
    unique = []
    for key, label in options:
        if key in seen:
            continue
        seen.add(key)
        unique.append((key, label))
    return unique


def _custom_plot_dataset_y_options(records) -> list[tuple[str, str]]:
    options: list[tuple[str, str]] = []
    for record_index, record in enumerate(list(records or [])):
        base_label = str(record.get("name") or record.get("dataset_type") or f"dataset {record_index + 1}")
        options.append((f"record:{record_index}|dataset", base_label))
    return options


def _custom_plot_split_y_key(y_key: str) -> tuple[int | None, str]:
    text = str(y_key or "")
    if text.startswith("record:") and "|" in text:
        head, inner = text.split("|", 1)
        try:
            return int(head.split(":", 1)[1]), inner
        except (TypeError, ValueError, IndexError):
            return None, inner
    return None, text


def _custom_plot_resolve_y(record: dict, y_key: str, parameters: dict | None = None):
    params = dict(parameters or {})
    x, x_tick_labels, resolved_x_label, transpose_features, matrix = _custom_plot_x_axis(record, params)
    if matrix.ndim != 2 or matrix.size == 0:
        return np.zeros(0, dtype=float), np.zeros(0, dtype=float), [], "", "Y", False
    feature_labels = [str(label) for label in list((record or {}).get("feature_labels", []))]
    if len(feature_labels) != matrix.shape[1]:
        feature_labels = [f"feature {index + 1}" for index in range(matrix.shape[1])]
    sample_labels = [str(label) for label in list((record or {}).get("sample_labels", []))]
    if len(sample_labels) != matrix.shape[0]:
        sample_labels = [f"sample {index + 1}" for index in range(matrix.shape[0])]
    key = str(y_key or "all_features")
    if key == "dataset":
        if transpose_features:
            return x, matrix[0, :], x_tick_labels, resolved_x_label, str(record.get("name") or record.get("dataset_type") or "dataset"), True
        if matrix.shape[1] == 1:
            return x, matrix[:, 0], x_tick_labels, resolved_x_label, str(record.get("name") or feature_labels[0]), False
        return x, matrix, x_tick_labels, resolved_x_label, str(record.get("name") or "dataset"), False
    if key.startswith("feature:"):
        try:
            col = int(key.split(":", 1)[1])
        except (TypeError, ValueError):
            col = 0
        col = min(max(0, col), max(0, matrix.shape[1] - 1))
        if matrix.shape[0] == 1 and matrix.shape[1] > 1:
            return x, matrix[0, :], x_tick_labels, resolved_x_label, feature_labels[col], transpose_features
        return x, matrix[:, col], x_tick_labels, resolved_x_label, feature_labels[col], False
    if key.startswith("sample:"):
        try:
            row = int(key.split(":", 1)[1])
        except (TypeError, ValueError):
            row = 0
        row = min(max(0, row), max(0, matrix.shape[0] - 1))
        values = matrix[row, :]
        x_values = np.arange(1, values.size + 1, dtype=float)
        labels = feature_labels if len(feature_labels) == values.size else []
        return x_values, values, labels, "Channel / feature", sample_labels[row], True
    if transpose_features:
        return x, matrix[0, :], x_tick_labels, resolved_x_label, str(record.get("dataset_type") or "value"), True
    if matrix.shape[1] == 1:
        return x, matrix[:, 0], x_tick_labels, resolved_x_label, feature_labels[0], False
    return x, matrix, x_tick_labels, resolved_x_label, "All features", False


def _custom_plot_aligned_points(x, y_values, x_tick_labels) -> list[tuple[tuple[str, object], str, float]]:
    y_array = np.asarray(y_values, dtype=float).reshape(-1)
    x_array = np.asarray(x, dtype=float).reshape(-1)
    labels = [str(label) for label in list(x_tick_labels or [])]
    points: list[tuple[tuple[str, object], str, float]] = []
    if labels and len(labels) == y_array.size:
        for label, value in zip(labels, y_array):
            key_text = normalize_channel_name(label) or str(label).strip().lower()
            points.append((("label", key_text), str(label), float(value)))
        return points
    if x_array.size == y_array.size:
        for value_x, value_y in zip(x_array, y_array):
            x_float = float(value_x)
            points.append((("numeric", round(x_float, 12)), f"{x_float:g}", float(value_y)))
        return points
    for index, value in enumerate(y_array):
        points.append((("index", index), str(index + 1), float(value)))
    return points


def _custom_plot_label(default_label: str, custom_label: str = "", suffix: str = "") -> str:
    custom = str(custom_label or "").strip()
    if custom:
        return f"{custom} {suffix}".strip()
    return str(default_label or suffix or "series").strip()


def _draw_custom_plot_figure(figure: Figure, records, parameters: dict | None = None):
    params = dict(parameters or {})
    record_list = list(records or [])
    figure.clear()
    ax = figure.add_subplot(111)
    mode = str(params.get("plot_mode", "auto") or "auto")
    x_mode = str(params.get("x_mode", "auto") or "auto")
    y_keys = [str(key) for key in list(params.get("y_data_keys") or []) if str(key)]
    if not y_keys:
        y_keys = ["all_features"]
    if len(y_keys) > 1 or params.get("plot_style") == "multi_y":
        plotted = 0
        resolved_axis_label = str(params.get("x_label", "") or "").strip()
        series_items: list[dict] = []
        axis_keys: list[tuple[str, object]] = []
        axis_labels: dict[tuple[str, object], str] = {}
        local_mode = "line" if mode == "auto" else mode
        legend_labels = [str(value or "").strip() for value in list(params.get("legend_labels") or [])]
        for y_index, y_key in enumerate(y_keys):
            custom_legend = legend_labels[y_index] if y_index < len(legend_labels) else ""
            record_index, inner_key = _custom_plot_split_y_key(y_key)
            if record_index is None:
                target_records = list(enumerate(record_list))
            elif 0 <= record_index < len(record_list):
                target_records = [(record_index, record_list[record_index])]
            else:
                target_records = []
            for current_index, record in target_records:
                base_label = str(record.get("name") or record.get("dataset_type") or f"dataset {current_index + 1}")
                x, y_values, x_tick_labels, resolved_x_label, y_name, _transpose = _custom_plot_resolve_y(record, inner_key, params)
                y_array = np.asarray(y_values, dtype=float)
                if y_array.ndim == 2:
                    for col in range(y_array.shape[1]):
                        default_label = f"{base_label}: {y_name} {col + 1}" if len(record_list) > 1 else f"{y_name} {col + 1}"
                        label = _custom_plot_label(default_label, custom_legend, str(col + 1) if y_array.shape[1] > 1 else "")
                        series = y_array[:, col]
                        points = _custom_plot_aligned_points(x, series, x_tick_labels)
                        series_items.append({"label": label, "points": points})
                        for key, display, _value in points:
                            if key not in axis_labels:
                                axis_keys.append(key)
                                axis_labels[key] = display
                        plotted += 1
                elif y_array.size:
                    default_label = f"{base_label}: {y_name}" if len(record_list) > 1 else y_name
                    label = _custom_plot_label(default_label, custom_legend)
                    points = _custom_plot_aligned_points(x, y_array, x_tick_labels)
                    series_items.append({"label": label, "points": points})
                    for key, display, _value in points:
                        if key not in axis_labels:
                            axis_keys.append(key)
                            axis_labels[key] = display
                    plotted += 1
                if not resolved_axis_label:
                    resolved_axis_label = resolved_x_label
        all_numeric_axis = bool(axis_keys) and all(key[0] == "numeric" for key in axis_keys)
        if all_numeric_axis:
            axis_keys = sorted(axis_keys, key=lambda key: float(key[1]))
        if all_numeric_axis:
            x_positions = np.asarray([float(key[1]) for key in axis_keys], dtype=float)
        else:
            x_positions = np.arange(1, len(axis_keys) + 1, dtype=float)
        if local_mode == "bar" and series_items:
            series_count = len(series_items)
            width = 0.78 / max(1, series_count)
            offsets = (np.arange(series_count) - (series_count - 1) / 2.0) * width
            for index, item in enumerate(series_items):
                y_by_key = {point_key: value for point_key, _display, value in item["points"]}
                y_values = np.asarray([y_by_key.get(key, np.nan) for key in axis_keys], dtype=float)
                mask = np.isfinite(y_values)
                if np.any(mask):
                    ax.bar(x_positions[mask] + offsets[index], y_values[mask], width=width, alpha=0.82, label=str(item["label"]))
        elif series_items:
            for item in series_items:
                y_by_key = {point_key: value for point_key, _display, value in item["points"]}
                y_values = np.asarray([y_by_key.get(key, np.nan) for key in axis_keys], dtype=float)
                mask = np.isfinite(y_values)
                if np.any(mask):
                    ax.plot(x_positions[mask], y_values[mask], marker="o", linewidth=1.5, label=str(item["label"]))
        if plotted == 0:
            ax.text(0.5, 0.5, "No plottable data", ha="center", va="center")
            ax.set_xticks([])
            ax.set_yticks([])
        else:
            if axis_keys:
                ax.set_xticks(x_positions)
                if not all_numeric_axis:
                    tick_labels = [axis_labels.get(key, str(index + 1)) for index, key in enumerate(axis_keys)]
                    rotation = 70 if len(tick_labels) > 20 else 35
                    ax.set_xticklabels(tick_labels, rotation=rotation, ha="right", fontsize=7 if len(tick_labels) > 20 else 8)
                    if len(tick_labels) > 60:
                        stride = max(1, int(np.ceil(len(tick_labels) / 40)))
                        for index, label in enumerate(ax.get_xticklabels()):
                            label.set_visible(index % stride == 0)
                elif x_mode == "generated":
                    x0 = float(x_positions[0])
                    x1 = float(x_positions[-1]) if x_positions.size > 1 else x0 + 1.0
                    ax.set_xlim(x0, x1)
            ax.set_xlabel(resolved_axis_label or "Sample")
            ax.set_ylabel(str(params.get("y_label") or "Value"))
            ax.set_title("Custom plot")
            ax.legend(loc="best", fontsize=8)
            if any(label.get_visible() and len(label.get_text()) > 10 for label in ax.get_xticklabels()):
                ax.tick_params(axis="x", labelsize=7)
        return plotted

    plotted = 0
    resolved_axis_label = str(params.get("x_label", "") or "").strip()
    numeric_x_for_axis = None
    for record in record_list:
        x, x_tick_labels, resolved_x_label, transpose_features, matrix = _custom_plot_x_axis(record, params)
        if matrix.ndim != 2 or matrix.size == 0:
            continue
        if not x_tick_labels and numeric_x_for_axis is None and x.size:
            numeric_x_for_axis = np.asarray(x, dtype=float)
        local_mode = mode
        if local_mode == "auto":
            local_mode = "bar" if (transpose_features or matrix.shape[0] <= 8) and len(record_list) == 1 else "line"
        base_label = str(record.get("name") or record.get("dataset_type") or "dataset")
        feature_labels = list(record.get("feature_labels", []))
        if transpose_features:
            values = matrix[0, :]
            label = base_label if len(record_list) > 1 else str(record.get("dataset_type") or "value")
            if local_mode == "bar":
                ax.bar(x, values, width=0.72, alpha=0.82, label=label)
            else:
                ax.plot(x, values, marker="o", linewidth=1.5, label=label)
        elif local_mode == "bar" and len(record_list) == 1:
            width = 0.8 / max(1, matrix.shape[1])
            offsets = (np.arange(matrix.shape[1]) - (matrix.shape[1] - 1) / 2.0) * width
            for col in range(matrix.shape[1]):
                label = feature_labels[col] if col < len(feature_labels) else f"feature {col + 1}"
                ax.bar(x + offsets[col], matrix[:, col], width=width, alpha=0.82, label=label)
        else:
            for col in range(matrix.shape[1]):
                label = feature_labels[col] if col < len(feature_labels) else f"feature {col + 1}"
                ax.plot(x, matrix[:, col], marker="o", linewidth=1.4, label=f"{base_label}: {label}")
        if x_tick_labels and len(x_tick_labels) == len(x):
            ax.set_xticks(x)
            rotation = 70 if len(x_tick_labels) > 20 else 35
            ax.set_xticklabels(x_tick_labels, rotation=rotation, ha="right", fontsize=7 if len(x_tick_labels) > 20 else 8)
            if len(x_tick_labels) > 60:
                stride = max(1, int(np.ceil(len(x_tick_labels) / 40)))
                for index, label in enumerate(ax.get_xticklabels()):
                    label.set_visible(index % stride == 0)
        if not resolved_axis_label:
            resolved_axis_label = resolved_x_label
        plotted += 1
    if plotted == 0:
        ax.text(0.5, 0.5, "No plottable data", ha="center", va="center")
        ax.set_xticks([])
        ax.set_yticks([])
    else:
        if numeric_x_for_axis is not None and numeric_x_for_axis.size:
            ax.set_xticks(numeric_x_for_axis)
            if x_mode in {"generated", "sample_index"}:
                x0 = float(numeric_x_for_axis[0])
                x1 = float(numeric_x_for_axis[-1]) if numeric_x_for_axis.size > 1 else x0 + 1.0
                ax.set_xlim(x0, x1)
        ax.set_xlabel(resolved_axis_label or "Sample")
        ax.set_ylabel(str(params.get("y_label") or "Value"))
        ax.set_title("Custom plot")
        if plotted <= 2:
            ax.legend(loc="best", fontsize=8)
        if any(label.get_visible() and len(label.get_text()) > 10 for label in ax.get_xticklabels()):
            ax.tick_params(axis="x", labelsize=7)
    return plotted


def _custom_filter_tokens(text: str) -> list[str]:
    return [token.strip() for token in re.split(r"[,;\n]+", str(text or "")) if token.strip()]


def _custom_label_filter_indices(labels, text: str) -> list[int]:
    tokens = _custom_filter_tokens(text)
    label_list = [str(label) for label in labels]
    if not tokens:
        return list(range(len(label_list)))
    selected: list[int] = []
    normalized_labels = [normalize_channel_name(label) for label in label_list]
    base_labels = [normalize_channel_name(_base_channel_from_raster_label(label)) for label in label_list]
    for token in tokens:
        token_key = normalize_channel_name(token)
        exact_matches = [
            index
            for index, (label_key, base_key) in enumerate(zip(normalized_labels, base_labels))
            if token_key and (token_key == label_key or token_key == base_key)
        ]
        matches = exact_matches
        if not matches:
            token_lower = str(token).lower()
            matches = [index for index, label in enumerate(label_list) if token_lower in str(label).lower()]
        for index in matches:
            if index not in selected:
                selected.append(index)
    return selected


def _custom_extract_processed_record(record: dict, parameters: dict | None = None) -> dict:
    params = dict(parameters or {})
    matrix = np.asarray((record or {}).get("matrix", []), dtype=float)
    if matrix.ndim == 1:
        matrix = matrix.reshape((-1, 1))
    if matrix.ndim != 2:
        matrix = np.zeros((0, 0), dtype=float)
    sample_labels = [str(label) for label in list((record or {}).get("sample_labels", []))]
    feature_labels = [str(label) for label in list((record or {}).get("feature_labels", []))]
    if len(sample_labels) != matrix.shape[0]:
        sample_labels = [f"sample {index + 1}" for index in range(matrix.shape[0])]
    if len(feature_labels) != matrix.shape[1]:
        feature_labels = [f"feature {index + 1}" for index in range(matrix.shape[1])]
    sample_indices = _custom_label_filter_indices(sample_labels, str(params.get("sample_filter", "")))
    feature_indices = _custom_label_filter_indices(feature_labels, str(params.get("feature_filter", "")))
    sample_indices = [index for index in sample_indices if 0 <= index < matrix.shape[0]]
    feature_indices = [index for index in feature_indices if 0 <= index < matrix.shape[1]]
    if not sample_indices or not feature_indices:
        extracted = np.zeros((0, 0), dtype=float)
    else:
        extracted = matrix[np.ix_(sample_indices, feature_indices)]
    output = dict(record or {})
    output["matrix"] = extracted
    output["sample_labels"] = [sample_labels[index] for index in sample_indices]
    output["feature_labels"] = [feature_labels[index] for index in feature_indices]
    output["description"] = f"{str((record or {}).get('description', '') or 'Processed data')} | extracted samples={len(sample_indices)} features={len(feature_indices)}"
    extraction = dict(params)
    extraction["source_processed_path"] = str((record or {}).get("path", ""))
    extraction["source_processed_name"] = str((record or {}).get("name", ""))
    output["custom_extraction"] = extraction
    if str(params.get("extracted_name", "")).strip():
        output["name"] = str(params.get("extracted_name", "")).strip()
    elif params.get("apply_filters"):
        output["name"] = f"{str((record or {}).get('name') or 'processed')} | extracted"
    return output


def _processed_dataset_label(record, *, view_mode: str) -> str:
    path = Path(str((record or {}).get("path", "")))
    source_name = path.name or str((record or {}).get("name", "") or "dataset")
    return f"{source_name} | {str(view_mode or 'auto')}"


def _processed_dataset_commit(parameters: dict | None) -> tuple[str, str]:
    params = dict(parameters or {})
    dataset_type = str(params.get("dataset_type", params.get("view_mode", "dataset")) or "dataset")
    dataset_group = str(params.get("dataset_group", "generic") or "generic")
    origin = str(params.get("origin", "manual") or "manual")
    bin_ms = float(params.get("bin_ms", 10.0))
    burst_window_ms = float(params.get("burst_window_ms", 300.0))
    burst_threshold_z = float(params.get("burst_threshold_z", 4.0))
    array_axis = str(params.get("array_axis", "rows") or "rows")

    if dataset_type == "burst_flat":
        title = f"{dataset_group} | burst detection cached"
        detail = (
            f"Generated from spike trains with burst detection; "
            f"view={params.get('view_mode', 'burst_flat')}, bin={bin_ms:g} ms, "
            f"burst window={burst_window_ms:g} ms, burst z-threshold={burst_threshold_z:g}, origin={origin}."
        )
        return title, detail
    if dataset_type == "channel_time":
        title = f"{dataset_group} | channel-time spike counts"
        detail = (
            f"Generated from spike trains using time-bin counting; "
            f"view={params.get('view_mode', 'channel_time')}, bin={bin_ms:g} ms, origin={origin}."
        )
        return title, detail
    if dataset_group == "array":
        title = "array | matrix import"
        detail = (
            f"Generated from array-like source data; "
            f"view={params.get('view_mode', 'auto')}, sample axis={array_axis}, origin={origin}."
        )
        return title, detail
    title = f"{dataset_group} | processed dataset"
    detail = (
        f"Generated with view={params.get('view_mode', 'auto')}, "
        f"bin={bin_ms:g} ms, burst window={burst_window_ms:g} ms, "
        f"burst z-threshold={burst_threshold_z:g}, sample axis={array_axis}, origin={origin}."
    )
    return title, detail


def _processed_dataset_presets_for_record(record) -> list[dict]:
    data = record.get("raw_data") if isinstance(record, dict) else None
    if isinstance(data, UnifiedMEAData):
        return [
            {
                "dataset_type": "channel_time",
                "dataset_group": "raster",
                "view_mode": "channel_time",
                "bin_ms": 10.0,
                "burst_window_ms": 300.0,
                "burst_threshold_z": 4.0,
                "array_axis": "rows",
                "origin": "auto-raster",
                "display_name": "Channel x time",
            },
            {
                "dataset_type": "burst_flat",
                "dataset_group": "burst",
                "view_mode": "burst_flat",
                "bin_ms": 10.0,
                "burst_window_ms": 300.0,
                "burst_threshold_z": 4.0,
                "array_axis": "rows",
                "origin": "auto-raster",
                "display_name": "Burst trajectory matrix",
            },
        ]
    return [
        {
            "dataset_type": "array_rows",
            "dataset_group": "array",
            "view_mode": "auto",
            "bin_ms": 10.0,
            "burst_window_ms": 300.0,
            "burst_threshold_z": 4.0,
            "array_axis": "rows",
            "origin": "auto-raster",
            "display_name": "Array rows",
        }
    ]


class FileDatabaseLoadWorker(QRunnable):
    def __init__(self, paths, *, selected_wells_by_path=None):
        super().__init__()
        self.paths = [str(path) for path in paths]
        self.selected_wells_by_path = dict(selected_wells_by_path or {})
        self.signals = WorkerSignals()
        self._cancel_requested = False

    def cancel(self) -> None:
        self._cancel_requested = True

    def _is_cancelled(self) -> bool:
        return bool(self._cancel_requested)

    @Slot()
    def run(self):
        records = []
        errors = []
        total = max(1, len(self.paths))
        try:
            for index, path_text in enumerate(self.paths):
                if self._is_cancelled():
                    raise InterruptedError("Data loading cancelled")
                path = Path(path_text)
                self.signals.progress.emit(
                    5 + int(87 * index / total),
                    f"Reading {path.name} ({index + 1}/{len(self.paths)})...",
                )
                try:
                    raw_data, data_kind = _load_gui_data_file(
                        path,
                        selected_wells=self.selected_wells_by_path.get(str(path)),
                        cancel_check=self._is_cancelled,
                    )
                    records.append({"path": str(path), "raw_data": raw_data, "data_kind": data_kind})
                except InterruptedError:
                    raise
                except Exception as exc:
                    errors.append(f"{path.name}: {exc}")
            if self._is_cancelled():
                raise InterruptedError("Data loading cancelled")
            self.signals.progress.emit(95, "Preparing file database...")
            self.signals.finished.emit({"records": records, "errors": errors})
        except InterruptedError as exc:
            self.signals.canceled.emit(str(exc) or "Data loading cancelled")
        except Exception:
            self.signals.failed.emit(traceback.format_exc())


class MaxwellWaveformLoadWorker(QRunnable):
    def __init__(self, path: str):
        super().__init__()
        self.path = path
        self.signals = WorkerSignals()
        self._cancel_requested = False

    def cancel(self) -> None:
        self._cancel_requested = True

    def _is_cancelled(self) -> bool:
        return bool(self._cancel_requested)

    @Slot()
    def run(self):
        try:
            if self._is_cancelled():
                raise InterruptedError("Waveform loading cancelled")
            self.signals.progress.emit(10, "Opening Maxwell raw data...")
            data = read_maxwell_h5(self.path, cancel_check=self._is_cancelled, extract_waveforms=True)
            if self._is_cancelled():
                raise InterruptedError("Waveform loading cancelled")
            self.signals.progress.emit(95, "Preparing waveforms...")
            self.signals.finished.emit(data)
        except InterruptedError as exc:
            self.signals.canceled.emit(str(exc) or "Waveform loading cancelled")
        except Exception:
            self.signals.failed.emit(traceback.format_exc())


class StimulusResponseWorker(QRunnable):
    def __init__(
        self,
        paths,
        *,
        pre_ms: float,
        response_ms: float,
        artifact_ms: float,
        zero_stimulus_index: int = 0,
        strong_response_window_ms: float = 50.0,
    ):
        super().__init__()
        self.paths = [str(path) for path in paths]
        self.pre_ms = float(pre_ms)
        self.response_ms = float(response_ms)
        self.artifact_ms = float(artifact_ms)
        self.zero_stimulus_index = int(zero_stimulus_index)
        self.strong_response_window_ms = float(strong_response_window_ms)
        self.signals = WorkerSignals()
        self._cancel_requested = False

    def cancel(self) -> None:
        self._cancel_requested = True

    def _is_cancelled(self) -> bool:
        return bool(self._cancel_requested)

    @Slot()
    def run(self):
        try:
            records = []
            errors = []
            total = max(1, len(self.paths))
            for index, path in enumerate(self.paths):
                if self._is_cancelled():
                    raise InterruptedError("Stimulus response analysis cancelled")
                self.signals.progress.emit(5 + int(80 * index / total), f"Reading {Path(path).name}...")
                try:
                    data = _load_spike_only_data(path, cancel_check=self._is_cancelled)
                    record = _stimulus_response_record_from_data(
                        path,
                        data,
                        pre_ms=self.pre_ms,
                        response_ms=self.response_ms,
                        artifact_ms=self.artifact_ms,
                        zero_stimulus_index=self.zero_stimulus_index,
                        strong_response_window_ms=self.strong_response_window_ms,
                    )
                    records.append(record)
                except Exception as exc:
                    errors.append(f"{Path(path).name}: {exc}")
            if self._is_cancelled():
                raise InterruptedError("Stimulus response analysis cancelled")
            self.signals.progress.emit(92, "Preparing stimulus response comparison...")
            self.signals.finished.emit(
                {
                    "records": records,
                    "errors": errors,
                    "pre_ms": self.pre_ms,
                    "response_ms": self.response_ms,
                    "artifact_ms": self.artifact_ms,
                    "zero_stimulus_index": self.zero_stimulus_index,
                    "strong_response_window_ms": self.strong_response_window_ms,
                    "paths": self.paths,
                }
            )
        except InterruptedError as exc:
            self.signals.canceled.emit(str(exc) or "Stimulus response analysis cancelled")
        except Exception:
            self.signals.failed.emit(traceback.format_exc())


class MultiFileFactorAnalysisWorker(QRunnable):
    def __init__(self, paths, parameters: dict):
        super().__init__()
        self.paths = [str(path) for path in paths]
        self.parameters = dict(parameters or {})
        self.signals = WorkerSignals()
        self._cancel_requested = False

    def cancel(self) -> None:
        self._cancel_requested = True

    def _is_cancelled(self) -> bool:
        return bool(self._cancel_requested)

    @Slot()
    def run(self):
        try:
            payload = _multi_file_factor_analysis_payload(
                self.paths,
                cancel_check=self._is_cancelled,
                progress=self.signals.progress.emit,
                **self.parameters,
            )
            if self._is_cancelled():
                raise InterruptedError("Multi-file factor analysis cancelled")
            self.signals.finished.emit(payload)
        except InterruptedError as exc:
            self.signals.canceled.emit(str(exc) or "Multi-file factor analysis cancelled")
        except Exception:
            self.signals.failed.emit(traceback.format_exc())


class DataFilesInputDialog(AppDialog):
    def __init__(self, parent=None, initial_paths=None):
        super().__init__(parent)
        self.setWindowTitle("Open Data Files")
        self.resize(860, 520)
        self.paths: list[str] = []

        self.table = QTableWidget(0, 3)
        self.table.setHorizontalHeaderLabels(["File", "Type", "Folder"])
        self.table.setSelectionBehavior(QTableWidget.SelectionBehavior.SelectRows)
        self.table.setSelectionMode(QTableWidget.SelectionMode.ExtendedSelection)

        add_files = QPushButton("Add Files")
        add_files.clicked.connect(self._add_files)
        add_folder = QPushButton("Add Folder")
        add_folder.clicked.connect(self._add_folder)
        remove = QPushButton("Remove")
        remove.clicked.connect(self._remove_selected)
        cancel = QPushButton("Cancel")
        cancel.clicked.connect(self.reject)
        load = QPushButton("Load")
        load.setObjectName("PrimaryButton")
        load.clicked.connect(self.accept)

        controls = QHBoxLayout()
        controls.addStretch(1)
        controls.addWidget(add_files)
        controls.addWidget(add_folder)
        controls.addWidget(remove)
        controls.addWidget(cancel)
        controls.addWidget(load)

        layout = QVBoxLayout(self)
        layout.addWidget(QLabel("Add data files directly, or add folders recursively. Maxwell H5 files load spikes first; waveforms are loaded later for sorting."))
        layout.addWidget(self.table, 1)
        layout.addLayout(controls)

        if initial_paths:
            self._add_paths(initial_paths)

    def _add_paths(self, paths) -> None:
        files = _data_file_supported_files(paths)
        existing = set(self.paths)
        for path in files:
            path_text = str(path)
            if path_text not in existing:
                self.paths.append(path_text)
                existing.add(path_text)
        self.paths.sort(key=str.lower)
        self._refresh_table()

    def _add_files(self) -> None:
        paths, _ = QFileDialog.getOpenFileNames(
            self,
            "Add data files",
            "data",
            "Data files (*.npy *.npz *.csv *.txt *.tsv *.nev *.spk *.h5 *.hdf5);;Array files (*.npy *.npz *.csv *.txt *.tsv);;Spike files (*.nev *.spk *.h5 *.hdf5 *.npz);;All files (*)",
        )
        self._add_paths(paths)

    def _add_folder(self) -> None:
        path = QFileDialog.getExistingDirectory(self, "Add data folder", "data")
        if path:
            self._add_paths([path])

    def _remove_selected(self) -> None:
        selected_rows = sorted({index.row() for index in self.table.selectedIndexes()}, reverse=True)
        for row in selected_rows:
            if 0 <= row < len(self.paths):
                self.paths.pop(row)
        self._refresh_table()

    def _refresh_table(self) -> None:
        self.table.setRowCount(len(self.paths))
        for row, path_text in enumerate(self.paths):
            path = Path(path_text)
            values = [path.name, path.suffix.lower().lstrip(".") or "file", str(path.parent)]
            for column, value in enumerate(values):
                item = QTableWidgetItem(str(value))
                if column == 0:
                    item.setData(Qt.ItemDataRole.UserRole, path_text)
                self.table.setItem(row, column, item)
        self.table.resizeColumnsToContents()

    def values(self) -> list[str]:
        return list(self.paths)


class _DatabaseAnalysisDialogBase(AppDialog):
    def _setup_database_table(self):
        self.database_sort_column = None
        self.table = QTableWidget(0, 6)
        self.table.setHorizontalHeaderLabels(["File", "Kind", "Label", "Channels", "Spikes", "Folder"])
        self.table.setSelectionBehavior(QTableWidget.SelectionBehavior.SelectRows)
        self.table.setSelectionMode(QTableWidget.SelectionMode.ExtendedSelection)
        table_header = self.table.horizontalHeader()
        table_header.setSectionsClickable(True)
        table_header.setSortIndicatorShown(False)
        table_header.sectionClicked.connect(self._database_header_clicked)

    def _set_records(self, records) -> None:
        selected_paths = set()
        if hasattr(self, "table") and self.table.rowCount():
            for index in self.table.selectedIndexes():
                item = self.table.item(index.row(), 0)
                if item is not None:
                    path_text = str(item.data(Qt.ItemDataRole.UserRole) or "")
                    if path_text:
                        selected_paths.add(path_text)
        self.records = list(records or [])
        self._ensure_database_order()
        if self.database_sort_column is not None:
            column = int(self.database_sort_column)
            self.records.sort(key=lambda record: (self._database_sort_value(record, column), self._database_default_sort_key(record)))
        self.table.setRowCount(len(self.records))
        for row, record in enumerate(self.records):
            path = Path(str(record.get("path", "")))
            data = record.get("raw_data")
            channels, spikes, _waveforms = _loaded_data_stats(data)
            values = [
                path.name,
                _loaded_data_kind_label(data, str(record.get("data_kind", ""))),
                _loaded_data_activity_label(path, data),
                str(channels),
                str(spikes),
                str(path.parent),
            ]
            for column, value in enumerate(values):
                item = QTableWidgetItem(str(value))
                item.setData(Qt.ItemDataRole.UserRole, str(path))
                self.table.setItem(row, column, item)
        self.table.resizeColumnsToContents()
        self._restore_selected_paths(selected_paths)

    def _ensure_database_order(self) -> None:
        for index, record in enumerate(self.records):
            if isinstance(record, dict) and "_database_order" not in record:
                record["_database_order"] = index

    def _database_header_clicked(self, column: int) -> None:
        if not self.records:
            return
        if self.database_sort_column == int(column):
            self.database_sort_column = None
            self._reorder_database_records(lambda record: self._database_default_sort_key(record))
            return
        self.database_sort_column = int(column)
        self._reorder_database_records(
            lambda record: (self._database_sort_value(record, int(column)), self._database_default_sort_key(record))
        )

    def _database_default_sort_key(self, record: dict) -> tuple[int, str]:
        try:
            order = int(record.get("_database_order", 0))
        except (AttributeError, TypeError, ValueError):
            order = 0
        return (order, str((record or {}).get("path", "")).lower())

    def _database_sort_value(self, record: dict, column: int):
        path = Path(str((record or {}).get("path", "")))
        data = (record or {}).get("raw_data")
        channels, spikes, _waveforms = _loaded_data_stats(data)
        values = {
            0: str(path.name).lower(),
            1: _loaded_data_kind_label(data, str((record or {}).get("data_kind", ""))).lower(),
            2: _loaded_data_activity_sort_key(_loaded_data_activity_label(path, data)),
            3: int(channels),
            4: int(spikes),
            5: str(path.parent).lower(),
        }
        return values.get(int(column), str(path).lower())

    def _reorder_database_records(self, key) -> None:
        selected_paths = {
            str(self.records[row].get("path", ""))
            for row in self._selected_rows()
            if 0 <= row < len(self.records)
        }
        self.records.sort(key=key)
        self._set_records(self.records)
        if selected_paths:
            self.table.clearSelection()
            self._restore_selected_paths(selected_paths)

    def _restore_selected_paths(self, selected_paths) -> None:
        self.table.clearSelection()
        if not self.records:
            return
        selection_model = self.table.selectionModel()
        flags = QItemSelectionModel.SelectionFlag.Select | QItemSelectionModel.SelectionFlag.Rows
        matched = False
        if selected_paths and selection_model is not None:
            for row, record in enumerate(self.records):
                if str(record.get("path", "")) in selected_paths:
                    selection_model.select(self.table.model().index(row, 0), flags)
                    if not matched:
                        self.table.setCurrentCell(row, 0)
                    matched = True
        if not matched:
            self.table.selectAll()

    def _selected_rows(self) -> list[int]:
        rows = sorted({index.row() for index in self.table.selectedIndexes()})
        return [row for row in rows if 0 <= row < len(self.records)]

    def _selected_records(self) -> list[dict]:
        return [self.records[row] for row in self._selected_rows()]

    def _selected_paths(self) -> list[str]:
        return [
            str(self.records[row].get("path", ""))
            for row in self._selected_rows()
            if 0 <= row < len(self.records) and self.records[row].get("path")
        ]


